from typing import Tuple

def resolve_token_bucket_window(
    current_tokens: float,
    capacity: float,
    fill_rate_per_sec: float,
    elapsed_seconds: float,
    requested_tokens: float
) -> Tuple[bool, float, float]:
    if capacity <= 0.0:
        raise ValueError('Capacity must be strictly positive.')
    if requested_tokens <= 0.0:
        raise ValueError('Requested tokens must be strictly positive.')
    if current_tokens < 0.0 or fill_rate_per_sec < 0.0 or elapsed_seconds < 0.0:
        raise ValueError('Token balances and rates cannot be negative.')

    refilled = min(capacity, current_tokens + (fill_rate_per_sec * elapsed_seconds))
    if requested_tokens <= refilled + 1e-9:
        remaining = max(0.0, refilled - requested_tokens)
        return True, round(remaining, 6), 0.0
    else:
        deficit = requested_tokens - refilled
        retry_after = 0.0 if fill_rate_per_sec <= 0.0 else (deficit / fill_rate_per_sec)
        return False, round(refilled, 6), round(retry_after, 6)
